"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["16427"],{96249(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.peso_area_enem.area_faltando","status":422,"titulo":"Falta o peso de alguma das cinco \xe1reas"},"descricao":{"codigo":"uniplus.configuracao.peso_area_enem.area_faltando","requisitos":["UNI-REQ-0174"],"oQueAconteceu":["Cada linha de pesos por \xe1rea do ENEM traz o peso das cinco \xe1reas: Reda\xe7\xe3o, Ci\xeancias da Natureza, Ci\xeancias Humanas, Linguagens e Matem\xe1tica. Os pesos de cada grupo de \xe1rea v\xeam do Anexo I da Resolu\xe7\xe3o n\xba 805/2024/Consepe, da Unifesspa, que d\xe1 o peso de cada uma das cinco \xe1reas. A nota da etapa do ENEM \xe9 a m\xe9dia das cinco \xe1reas ponderada por esses pesos (UNI-REQ-0174), e por isso nenhuma pode faltar. A lista `areas` enviada n\xe3o traz o peso de pelo menos uma delas, ou n\xe3o foi enviada.","A recusa vem na lista `errors` da resposta, com `field` igual a `areas`, e a mensagem cita os c\xf3digos das \xe1reas que faltaram. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, o corpo \xe9 conferido antes da busca da linha: um `{id}` que n\xe3o existe s\xf3 responde como n\xe3o encontrado quando o corpo \xe9 v\xe1lido."],"comoResolver":["Envie as cinco \xe1reas, uma vez cada, com o c\xf3digo e o peso de cada uma. As \xe1reas aceitas e os r\xf3tulos oficiais v\xeam de `GET /api/configuracao/pesos-area-enem/areas`. O campo `peso` de cada item \xe9 obrigat\xf3rio: o item sem ele \xe9 recusado no pr\xf3prio campo, com [peso da \xe1rea obrigat\xf3rio](/erros/uniplus.configuracao.peso_area_enem.peso_obrigatorio), junto das demais recusas do corpo. Na atualiza\xe7\xe3o, o corpo substitui a linha inteira: as cinco \xe1reas v\xe3o sempre, e o corte, quando ausente, significa que a \xe1rea fica sem corte."],"ondeAparece":["Cadastro dos pesos por \xe1rea do ENEM","Atualiza\xe7\xe3o dos pesos por \xe1rea do ENEM"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Peso area enem"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);